def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    x = []
    for v in history:
        try:
            z = float(v)
            if math.isfinite(z):
                x.append(z)
        except (TypeError, ValueError):
            pass
    if h == 0:
        return []
    if not x:
        return [0.0] * h
    n = len(x)
    periods = [p for p in range(24, 49) if n >= 4 * p]
    if not periods:
        return [x[-1]] * h
    def lag_score(p):
        start = max(p, n - 6 * p)
        errors = [abs(x[t] - x[t - p]) for t in range(start, n)]
        return statistics.median(errors) + 0.1 * statistics.mean(errors)
    p = min(periods, key=lag_score)
    nonnegative = min(x) >= 0.0
    lo = min(x[-min(n, 6 * p):])
    hi = max(x[-min(n, 6 * p):])
    spread = statistics.median([abs(v - statistics.median(x[-min(n, 6 * p):])) for v in x[-min(n, 6 * p):]]) + 1e-9
    out = []
    for j in range(h):
        target = n + j
        ids = list(range(target % p, n, p))[-6:]
        if len(ids) < 2:
            value = out[j - p] if j >= p else x[-1]
        else:
            slopes = []
            for a in range(len(ids)):
                for b in range(a + 1, len(ids)):
                    slopes.append((x[ids[b]] - x[ids[a]]) / ((ids[b] - ids[a]) / p))
            slope = statistics.median(slopes)
            diffs = [x[ids[k]] - x[ids[k - 1]] for k in range(1, len(ids))]
            dc = statistics.median(diffs)
            mad = statistics.median([abs(d - dc) for d in diffs]) + 1e-9
            slope = max(dc - 3.0 * mad, min(dc + 3.0 * mad, slope))
            intercepts = [x[q] - slope * (q / p) for q in ids]
            value = statistics.median(intercepts) + slope * (target / p)
        value = max(lo - 2.0 * spread, min(hi + 2.0 * spread, value))
        if nonnegative:
            value = max(0.0, value)
        out.append(float(value))
    return out
